//
// The lab console: draws the lab from lab.json (generated by demo-gen) and
// opens a terminal tab per device. Each tab is ttyd under /t/, which logs in
// to the device named in `?arg=`. The page holds no password.

"use strict";

const SVG = "http://www.w3.org/2000/svg";
const WIDTH = 360;
const LAYER_GAP = 96;
const TOP = 34;
const RADIUS = 18;
// The provider first, then one colour per organization in the order they appear.
const UPSTREAM_COLOUR = "#7d8590";
const PALETTE = ["#1f6feb", "#1a7f37", "#cf222e", "#8250df", "#bf8700", "#0a7f8f"];
const LINK_KINDS = [
  ["eBGP", "ebgp", "eBGP to the provider"],
  ["OSPF", "ospf", "OSPF"],
  ["LAN", "lan", "Services LAN"],
];

const sessions = new Map(); // device name -> { tab, frame }
let active = null;
let nodesByName = new Map();
let colours = new Map();

function el(name, attrs = {}, parent = null) {
  const node = document.createElementNS(SVG, name);
  for (const [key, value] of Object.entries(attrs)) {
    node.setAttribute(key, value);
  }
  if (parent) {
    parent.appendChild(node);
  }
  return node;
}

// Positions per layer; inside a layer, a node sits under the average of its
// neighbours one layer up, so the lines cross as little as they can.
function layout(nodes, links) {
  const neighbours = new Map(nodes.map((n) => [n.name, []]));
  for (const link of links) {
    neighbours.get(link.a).push(link.b);
    neighbours.get(link.b).push(link.a);
  }
  const layers = [];
  for (const node of nodes) {
    (layers[node.layer] ||= []).push(node);
  }
  const x = new Map();
  layers.forEach((layer, depth) => {
    if (depth > 0) {
      const above = (n) => {
        const xs = neighbours
          .get(n.name)
          .map((m) => nodesByName.get(m))
          .filter((m) => m.layer === depth - 1)
          .map((m) => x.get(m.name));
        return xs.length ? xs.reduce((a, b) => a + b, 0) / xs.length : WIDTH / 2;
      };
      layer.sort((a, b) => above(a) - above(b) || a.name.localeCompare(b.name));
    }
    const step = WIDTH / layer.length;
    layer.forEach((node, i) => x.set(node.name, step * (i + 0.5)));
  });
  return { x, depth: layers.length };
}

function drawMap(data) {
  const svg = document.getElementById("map");
  const { x, depth } = layout(data.nodes, data.links);
  const y = (node) => TOP + node.layer * LAYER_GAP;
  const height = TOP + (depth - 1) * LAYER_GAP + 52;
  svg.setAttribute("viewBox", `0 0 ${WIDTH} ${height}`);

  const links = el("g", {}, svg);
  for (const link of data.links) {
    const a = nodesByName.get(link.a);
    const b = nodesByName.get(link.b);
    const line = el(
      "line",
      {
        class: `link ${link.protocol.toLowerCase()}`,
        x1: x.get(a.name),
        y1: y(a),
        x2: x.get(b.name),
        y2: y(b),
      },
      links,
    );
    el("title", {}, line).textContent = `${link.a} – ${link.b} (${link.protocol})`;
  }

  for (const node of data.nodes) {
    const cx = x.get(node.name);
    const cy = y(node);
    const group = el(
      "g",
      {
        class: "node",
        tabindex: "0",
        role: "button",
        "data-name": node.name,
        "aria-label": `Open a terminal on ${node.name}`,
      },
      svg,
    );
    el("title", {}, group).textContent =
      `${node.name}\n${node.owner}, ${node.kind}\n` +
      `management ${node.management}\n${node.addresses.join(", ")}`;
    if (node.kind === "server") {
      el("rect", { class: "ring", x: cx - 22, y: cy - 19, width: 44, height: 38, rx: 9 }, group);
      el(
        "rect",
        {
          class: "shape",
          x: cx - 17,
          y: cy - 14,
          width: 34,
          height: 28,
          rx: 6,
          fill: colours.get(node.org),
        },
        group,
      );
    } else {
      el("circle", { class: "ring", cx, cy, r: RADIUS + 5 }, group);
      el("circle", { class: "shape", cx, cy, r: RADIUS, fill: colours.get(node.org) }, group);
    }
    const glyph = el("text", { class: "glyph", x: cx, y: cy + 4 }, group);
    glyph.textContent = node.kind === "server" ? "S" : "R";
    const label = el("text", { x: cx, y: cy + 36 }, group);
    label.textContent = node.name;
    group.addEventListener("click", () => open(node.name));
    group.addEventListener("keydown", (event) => {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        open(node.name);
      }
    });
  }
}

function drawLegend(data) {
  const legend = document.getElementById("legend");
  const owners = new Map(data.nodes.map((n) => [n.org, n.owner]));
  for (const [org, owner] of owners) {
    const item = document.createElement("li");
    const swatch = document.createElement("span");
    swatch.className = "swatch";
    swatch.style.background = colours.get(org);
    item.append(swatch, owner);
    legend.appendChild(item);
  }
  const used = new Set(data.links.map((l) => l.protocol));
  for (const [protocol, css, text] of LINK_KINDS) {
    if (!used.has(protocol)) {
      continue;
    }
    const item = document.createElement("li");
    const stroke = document.createElement("span");
    stroke.className = `stroke ${css}`;
    item.append(stroke, text);
    legend.appendChild(item);
  }
}

function markNodes() {
  for (const group of document.querySelectorAll("#map .node")) {
    const name = group.dataset.name;
    group.classList.toggle("open", sessions.has(name));
    group.classList.toggle("active", name === active);
  }
}

function focusTerminal(frame) {
  try {
    const term = frame.contentWindow && frame.contentWindow.term;
    if (term) {
      term.focus();
      return;
    }
  } catch {
    // Not loaded yet: the load handler focuses it.
  }
  frame.focus();
}

function show(name) {
  active = name;
  for (const [key, session] of sessions) {
    const on = key === name;
    session.tab.classList.toggle("active", on);
    session.tab.setAttribute("aria-selected", String(on));
    session.frame.classList.toggle("active", on);
  }
  document.getElementById("empty").hidden = sessions.size > 0;
  markNodes();
  if (name) {
    const { tab, frame } = sessions.get(name);
    tab.scrollIntoView({ block: "nearest", inline: "nearest" });
    focusTerminal(frame);
  }
}

function open(name) {
  if (!sessions.has(name)) {
    const node = nodesByName.get(name);
    const tab = document.createElement("button");
    tab.type = "button";
    tab.className = "tab";
    tab.setAttribute("role", "tab");
    tab.title = `${node.owner}, ${node.kind}, ${node.management}`;
    const dot = document.createElement("span");
    dot.className = "dot";
    dot.style.background = colours.get(node.org);
    const close = document.createElement("span");
    close.className = "close";
    close.setAttribute("role", "button");
    close.setAttribute("aria-label", `Close ${name}`);
    close.textContent = "×";
    tab.append(dot, name, close);
    tab.addEventListener("click", (event) => {
      if (event.target === close) {
        shut(name);
      } else {
        show(name);
      }
    });
    tab.addEventListener("auxclick", (event) => {
      if (event.button === 1) {
        shut(name);
      }
    });
    const frame = document.createElement("iframe");
    frame.title = `Terminal on ${name}`;
    frame.src = `/t/?arg=${encodeURIComponent(name)}`;
    frame.addEventListener("load", () => {
      if (active === name) {
        focusTerminal(frame);
      }
    });
    document.getElementById("tabs").appendChild(tab);
    document.getElementById("frames").appendChild(frame);
    sessions.set(name, { tab, frame });
  }
  show(name);
}

function shut(name) {
  const session = sessions.get(name);
  if (!session) {
    return;
  }
  const names = [...sessions.keys()];
  const index = names.indexOf(name);
  session.tab.remove();
  session.frame.remove();
  sessions.delete(name);
  if (active === name) {
    const rest = names.filter((n) => n !== name);
    show(rest[Math.min(index, rest.length - 1)] || null);
  } else {
    markNodes();
  }
}

async function main() {
  const response = await fetch("lab.json", { cache: "no-store" });
  const data = await response.json();
  nodesByName = new Map(data.nodes.map((n) => [n.name, n]));
  let next = 0;
  for (const node of data.nodes) {
    if (!colours.has(node.org)) {
      colours.set(
        node.org,
        node.org === "upstream" ? UPSTREAM_COLOUR : PALETTE[next++ % PALETTE.length],
      );
    }
  }
  drawMap(data);
  drawLegend(data);
  document.getElementById("open-all").addEventListener("click", () => {
    const first = active;
    for (const node of data.nodes) {
      open(node.name);
    }
    show(first || data.nodes[0].name);
  });
}

main().catch((error) => {
  document.getElementById("empty").textContent = `Cannot load the lab map: ${error}`;
});
